    39  /*
    40   * Manifest names for the gnss_type enum - must be kept synced with it.
    41   * Also, masks so we can tell what packet types correspond to each class.
    42   */
    43  // the map of device class names
    44  struct classmap_t {
    45      char        *name;
    46      int         typemask;
    47      int         packetmask;
    48  };
    49  #define CLASSMAP_NITEMS 5
    50
    51  struct classmap_t classmap[CLASSMAP_NITEMS] = {
    52      // name     typemask        packetmask
    53      {"ANY",     0,              0},
    54      {"GPS",     SEEN_GPS,       GPS_TYPEMASK},
    55      {"RTCM2",   SEEN_RTCM2,     PACKET_TYPEMASK(RTCM2_PACKET)},
    56      {"RTCM3",   SEEN_RTCM3,     PACKET_TYPEMASK(RTCM3_PACKET)},
    57      {"AIS",     SEEN_AIS,       PACKET_TYPEMASK(AIVDM_PACKET)},
    58  };
    59  // *INDENT-ON*
