    61  // prevent negative zero confusion.
    62  // Dif arch will return 0.0, or -0.0.
    63  static inline double fix_zero(double d, double p)
    64  {
    65      // prevent -0.000
    66      if (fabs(d) < p) {
    67          return 0.0;
    68      }
    69      return d;
    70  }
    71
    72  // escape double quotes and control characters inside a JSON string
    73  char *json_stringify(char *to, size_t len, const char *from)
    74  {
    75      const char *sp;
    76      char *tp;
    77
    78      tp = to;
    79      /*
    80       * The limit is len-6 here because we need to be leave room for
    81       * each character to generate an up to 6-character Java-style
    82       * escape
    83       */
    84      for (sp = from; *sp != '\0' && ((tp - to) < ((int)len - 6)); sp++) {
    85          if (!isascii((unsigned char) *sp) ||
    86              iscntrl((unsigned char) *sp)) {
    87              *tp++ = '\\';
    88              switch (*sp) {
    89              case '\b':
    90                  *tp++ = 'b';
    91                  break;
    92              case '\f':
    93                  *tp++ = 'f';
    94                  break;
    95              case '\n':
    96                  *tp++ = 'n';
    97                  break;
    98              case '\r':
    99                  *tp++ = 'r';
   100                  break;
   101              case '\t':
   102                  *tp++ = 't';
   103                  break;
   104              default:
   105                  /* ugh, we'd prefer a C-style escape here, but this is JSON
   106                   * http://www.ietf.org/rfc/rfc4627.txt
   107                   * section 2.5, escape is \uXXX
   108                   * don't forget the NUL in the output count! */
   109                  (void)snprintf(tp, 6, "u%04x", 0x00ff & (unsigned int)*sp);
   110                  tp += strlen(tp);
   111              }
   112          } else {
   113              if ('"' == *sp ||
   114                  '\\' == *sp) {
   115                  *tp++ = '\\';
   116              }
   117              *tp++ = *sp;
   118          }
   119      }
   120      *tp = '\0';

